Here's a complete game, "Orb Runner": move with the mouse or WASD/arrow keys, collect glowing orbs, and dodge red hazards. Hazards get faster and more numerous over time. Reach 100 points to win; touching a hazard ends the run. Press Space/Enter or click to start and restart.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Orb Runner</title>
<style>
  html,body{margin:0;height:100%;background:#05060f;display:flex;align-items:center;justify-content:center;overflow:hidden}
  canvas{background:radial-gradient(circle at 50% 40%,#101436,#05060f);border:2px solid #2a3170;box-shadow:0 0 30px #2a3170;max-width:100vw;max-height:100vh}
</style>
</head>
<body>
<canvas id="c" width="800" height="560"></canvas>
<script>
(function(){
  const cv = document.getElementById('c'), ctx = cv.getContext('2d');
  const W = cv.width, H = cv.height;
  const WIN_SCORE = 100;
  window.gameState = { score: 0, state: "menu" };

  let state = "menu", score = 0, time = 0, lives = 3;
  let player, orbs, hazards, particles, keys = {}, mouse = null, spawnT = 0, invuln = 0, last = 0;

  // ---- Sound (generated) ----
  let actx = null;
  function beep(freq, dur, type, vol, slide) {
    try {
      if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)();
      const o = actx.createOscillator(), g = actx.createGain();
      o.type = type || 'sine';
      o.frequency.setValueAtTime(freq, actx.currentTime);
      if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), actx.currentTime + dur);
      g.gain.setValueAtTime(vol || 0.1, actx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime + dur);
      o.connect(g); g.connect(actx.destination);
      o.start(); o.stop(actx.currentTime + dur);
    } catch (e) {}
  }

  function sync() { window.gameState = { score: score, state: state }; }

  function reset() {
    player = { x: W / 2, y: H / 2, r: 12 };
    orbs = []; hazards = []; particles = [];
    score = 0; time = 0; lives = 3; spawnT = 0; invuln = 0;
    for (let i = 0; i < 3; i++) addOrb();
    for (let i = 0; i < 3; i++) addHazard();
  }

  function addOrb() {
    let x, y, tries = 0;
    do {
      x = 30 + Math.random() * (W - 60);
      y = 70 + Math.random() * (H - 100);
      tries++;
    } while (tries < 20 && Math.hypot(x - player.x, y - player.y) < 80);
    orbs.push({ x, y, r: 9, ph: Math.random() * 6.28 });
  }

  function addHazard() {
    const diff = 1 + time / 20;
    const speed = (60 + Math.random() * 40) * Math.min(diff, 4);
    let x, y;
    const side = Math.floor(Math.random() * 4);
    if (side === 0) { x = -20; y = Math.random() * H; }
    else if (side === 1) { x = W + 20; y = Math.random() * H; }
    else if (side === 2) { x = Math.random() * W; y = -20; }
    else { x = Math.random() * W; y = H + 20; }
    // aim roughly toward the player's area with some randomness
    const tx = player.x + (Math.random() - 0.5) * 300, ty = player.y + (Math.random() - 0.5) * 300;
    const a = Math.atan2(ty - y, tx - x);
    hazards.push({ x, y, vx: Math.cos(a) * speed, vy: Math.sin(a) * speed, r: 11 + Math.random() * 8, rot: 0 });
  }

  function burst(x, y, color, n) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * 6.28, s = 40 + Math.random() * 160;
      particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life: 0.6, color });
    }
  }

  function start() {
    reset();
    state = "playing";
    sync();
    beep(440, 0.15, 'square', 0.06, 440);
  }

  function endGame(won) {
    state = won ? "won" : "over";
    sync();
    if (won) { beep(523, 0.2, 'triangle', 0.1, 500); }
    else { beep(300, 0.5, 'sawtooth', 0.1, -250); }
  }

  function update(dt) {
    time += dt;
    // movement
    const sp = 280;
    let dx = 0, dy = 0;
    if (keys['arrowleft'] || keys['a']) dx -= 1;
    if (keys['arrowright'] || keys['d']) dx += 1;
    if (keys['arrowup'] || keys['w']) dy -= 1;
    if (keys['arrowdown'] || keys['s']) dy += 1;
    if (dx || dy) {
      const l = Math.hypot(dx, dy);
      player.x += dx / l * sp * dt; player.y += dy / l * sp * dt;
      mouse = null;
    } else if (mouse) {
      const mx = mouse.x - player.x, my = mouse.y - player.y, d = Math.hypot(mx, my);
      if (d > 4) {
        const step = Math.min(d, 420 * dt);
        player.x += mx / d * step; player.y += my / d * step;
      }
    }
    player.x = Math.max(player.r, Math.min(W - player.r, player.x));
    player.y = Math.max(player.r, Math.min(H - player.r, player.y));
    if (invuln > 0) invuln -= dt;

    // difficulty: spawn more hazards over time
    spawnT += dt;
    const interval = Math.max(0.9, 4 - time * 0.04);
    if (spawnT > interval) { spawnT = 0; addHazard(); }
    const maxHaz = Math.min(30, 3 + Math.floor(time / 6));
    while (hazards.length < Math.min(maxHaz, 3)) addHazard();

    for (const h of hazards) {
      h.x += h.vx * dt; h.y += h.vy * dt; h.rot += dt * 3;
      // bounce off walls
      if (h.x < h.r && h.vx < 0 || h.x > W - h.r && h.vx > 0) { if (h.x > 0 && h.x < W) h.vx *= -1; }
      if (h.y < h.r && h.vy < 0 || h.y > H - h.r && h.vy > 0) { if (h.y > 0 && h.y < H) h.vy *= -1; }
    }
    // remove hazards far offscreen
    hazards = hazards.filter(h => h.x > -80 && h.x < W + 80 && h.y > -80 && h.y < H + 80);
    if (hazards.length > maxHaz) hazards.length = maxHaz;

    // orb collection
    for (let i = orbs.length - 1; i >= 0; i--) {
      const o = orbs[i];
      if (Math.hypot(o.x - player.x, o.y - player.y) < o.r + player.r) {
        orbs.splice(i, 1);
        score += 10;
        burst(o.x, o.y, '#7dffb2', 14);
        beep(660 + Math.min(score, 400), 0.12, 'sine', 0.1, 300);
        addOrb();
        sync();
        if (score >= WIN_SCORE) { endGame(true); return; }
      }
    }
    // hazards collision
    if (invuln <= 0) {
      for (const h of hazards) {
        if (Math.hypot(h.x - player.x, h.y - player.y) < h.r + player.r - 3) {
          lives--;
          burst(player.x, player.y, '#ff4a6a', 24);
          invuln = 1.5;
          if (lives <= 0) { endGame(false); return; }
          beep(200, 0.25, 'sawtooth', 0.1, -100);
          break;
        }
      }
    }
    for (const p of particles) { p.x += p.vx * dt; p.y += p.vy * dt; p.life -= dt; }
    particles = particles.filter(p => p.life > 0);
  }

  function glowCircle(x, y, r, color, blur) {
    ctx.shadowColor = color; ctx.shadowBlur = blur;
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.fill();
    ctx.shadowBlur = 0;
  }

  function text(str, x, y, size, color, align) {
    ctx.font = 'bold ' + size + 'px monospace';
    ctx.fillStyle = color || '#fff';
    ctx.textAlign = align || 'center';
    ctx.fillText(str, x, y);
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);
    if (state === "menu") {
      ctx.shadowColor = '#7dffb2'; ctx.shadowBlur = 20;
      text('ORB RUNNER', W / 2, 190, 64, '#7dffb2');
      ctx.shadowBlur = 0;
      text('Collect glowing orbs. Avoid the red hazards.', W / 2, 250, 20, '#cfd6ff');
      text('Move: Mouse  or  WASD / Arrow keys', W / 2, 300, 20, '#cfd6ff');
      text('Reach ' + WIN_SCORE + ' points to win. You have 3 lives.', W / 2, 330, 20, '#cfd6ff');
      text('It gets faster and more dangerous over time!', W / 2, 360, 20, '#ffb86b');
      if (Math.floor(performance.now() / 500) % 2) text('Press SPACE / ENTER or CLICK to start', W / 2, 440, 24, '#ffffff');
      return;
    }
    // orbs
    const t = performance.now() / 300;
    for (const o of orbs) {
      glowCircle(o.x, o.y, o.r + Math.sin(t + o.ph) * 2, '#7dffb2', 25);
      glowCircle(o.x, o.y, 3, '#ffffff', 0);
    }
    // hazards
    for (const h of hazards) {
      ctx.save(); ctx.translate(h.x, h.y); ctx.rotate(h.rot);
      ctx.shadowColor = '#ff2a4a'; ctx.shadowBlur = 18;
      ctx.fillStyle = '#ff3355';
      ctx.beginPath();
      for (let i = 0; i < 8; i++) {
        const a = i * Math.PI / 4, rr = i % 2 ? h.r * 0.55 : h.r;
        ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
      }
      ctx.closePath(); ctx.fill();
      ctx.restore();
    }
    ctx.shadowBlur = 0;
    // player
    if (!(invuln > 0 && Math.floor(invuln * 10) % 2)) glowCircle(player.x, player.y, player.r, '#6ab7ff', 22);
    // particles
    for (const p of particles) {
      ctx.globalAlpha = Math.max(0, p.life / 0.6);
      ctx.fillStyle = p.color;
      ctx.fillRect(p.x - 2, p.y - 2, 4, 4);
    }
    ctx.globalAlpha = 1;
    // HUD
    text('Score: ' + score, 16, 34, 24, '#ffffff', 'left');
    text('Lives: ' + '♥'.repeat(Math.max(0, lives)), W - 16, 34, 24, '#ff6b8a', 'right');
    text('Level ' + (1 + Math.floor(time / 10)), W / 2, 34, 18, '#ffb86b');

    if (state === "over" || state === "won") {
      ctx.fillStyle = 'rgba(5,6,15,0.75)'; ctx.fillRect(0, 0, W, H);
      if (state === "won") {
        text('YOU WIN!', W / 2, 230, 60, '#7dffb2');
      } else {
        text('GAME OVER', W / 2, 230, 60, '#ff4a6a');
      }
      text('Final score: ' + score, W / 2, 290, 28, '#ffffff');
      text('Press SPACE / ENTER or CLICK to play again', W / 2, 350, 22, '#cfd6ff');
    }
  }

  function loop(ts) {
    const dt = Math.min(0.05, (ts - last) / 1000 || 0);
    last = ts;
    if (state === "playing") update(dt);
    draw();
    requestAnimationFrame(loop);
  }

  function tryStart() { if (state !== "playing") start(); }

  window.addEventListener('keydown', e => {
    const k = e.key.toLowerCase();
    keys[k] = true;
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault();
    if (k === ' ' || k === 'enter') tryStart();
  });
  window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });
  cv.addEventListener('mousemove', e => {
    const r = cv.getBoundingClientRect();
    mouse = { x: (e.clientX - r.left) * W / r.width, y: (e.clientY - r.top) * H / r.height };
  });
  cv.addEventListener('mousedown', () => { tryStart(); });

  sync();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
